import { createProject } from '~/client';
import type { CreateProjectResponse, CreateProjectData, ProjectCreateRequest } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useCreateProject = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: ProjectCreateRequest): Promise<CreateProjectResponse> =>
      createProject({
        composable: '$fetch',
        body: ref(data),
      }),
    onSuccess: async (data) => {
      showToastSuccess(`Project created successfully`);
      await navigateTo({
        name: 'projects-id-edit-project-configuration',
        params: {
          id: data.id,
        },
      });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    createProject: mutateAsync,
    isCreateProjectLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
